@once
@push('styles')
<style>
.regencia-cabecera{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1.5rem;background:linear-gradient(120deg,var(--ui-primary-soft),var(--ui-surface));border-left:4px solid var(--ui-primary)}.regencia-herramientas{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}.regencia-indicadores{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.regencia-indicadores article{padding:1.1rem;display:grid;gap:.45rem}.regencia-indicadores strong{font-size:2rem;color:var(--ui-primary)}.regencia-indicadores span{font-size:.8rem;color:var(--ui-muted)}.regencia-vistas,.regencia-enlaces{display:flex;gap:.5rem;flex-wrap:wrap}.regencia-vistas [aria-pressed=true]{color:var(--ui-primary);border-color:var(--ui-primary);background:var(--ui-primary-soft)}.regencia-grafico,.regencia-conexiones,.regencia-registros{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.regencia-barra{display:grid;grid-template-columns:1fr auto;gap:.6rem;text-align:left;padding:1rem;border:1px solid var(--ui-border);border-radius:.85rem;color:var(--ui-text);background:var(--ui-surface-soft)}.regencia-barra small{grid-column:1/-1;color:var(--ui-muted)}.regencia-pista{grid-column:1/-1;height:.7rem;border-radius:1rem;overflow:hidden;background:var(--ui-border)}.regencia-pista i{display:block;height:100%;background:var(--ui-primary);transform-origin:left;transition:transform .35s ease-out}.regencia-filtros{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.regencia-tarjeta{padding:1.25rem;border:1px solid var(--ui-border);border-radius:1rem;background:var(--ui-surface-soft);animation:regencia-entrada .25s ease-out}.regencia-lista{grid-template-columns:1fr}.regencia-lista .regencia-tarjeta{display:grid;grid-template-columns:1fr 1fr;gap:.5rem 1rem}.regencia-vacio{grid-column:1/-1;padding:2rem;text-align:center;color:var(--ui-muted);line-height:1.6}.regencia-vacio>i{display:block;font-size:2rem;color:var(--ui-primary);margin-bottom:.7rem}.regencia-vacio strong{display:block;color:var(--ui-text)}.regencia-formulario{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:1.5rem}.regencia-formulario>aside{height:fit-content}.regencia-fechas{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.regencia-barra:focus-visible{outline:2px solid var(--ui-primary);outline-offset:3px}@keyframes regencia-entrada{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}@media(max-width:850px){.regencia-filtros,.regencia-indicadores,.regencia-grafico,.regencia-conexiones,.regencia-registros{grid-template-columns:repeat(2,minmax(0,1fr))}.regencia-lista,.regencia-formulario{grid-template-columns:1fr}}@media(max-width:600px){.regencia-cabecera{align-items:start;flex-direction:column;padding:1rem}.regencia-filtros,.regencia-grafico,.regencia-conexiones,.regencia-registros,.regencia-fechas{grid-template-columns:1fr}.regencia-lista .regencia-tarjeta{display:block}.regencia-vistas{width:100%}}@media(prefers-reduced-motion:reduce){.regencia-tarjeta{animation:none}.regencia-pista i{transition:none}}
</style>
<style>
.regencia-acompanamiento{border-top:3px solid var(--ui-primary)}.regencia-resumen-estudiantes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.regencia-resumen-estudiantes>div{display:flex;flex-direction:column;gap:.5rem;padding:1rem;border-radius:.9rem;border:1px solid var(--ui-border);background:var(--ui-surface-soft)}.regencia-resumen-estudiantes strong{font-size:2rem;color:var(--ui-text)}.regencia-resumen-estudiantes span{font-size:.8rem;color:var(--ui-muted)}.regencia-leyenda{display:flex;flex-wrap:wrap;gap:1rem;color:var(--ui-muted);font-size:.75rem}.regencia-leyenda>span{display:flex;gap:.4rem;align-items:center}.regencia-marca{width:.75rem;height:.75rem;border-radius:.25rem}.regencia-comparativa{display:grid;gap:.5rem}.regencia-comparativa-fila{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.5fr) minmax(0,1fr);gap:1rem;align-items:center;text-align:left;border:1px solid var(--ui-border);padding:1rem;border-radius:.9rem;background:var(--ui-surface-soft);color:var(--ui-text);transition:border-color .2s,transform .2s}.regencia-comparativa-fila:hover{border-color:var(--ui-primary);transform:translateY(-2px)}.regencia-comparativa-nombre{font-weight:600}.regencia-comparativa-nombre small,.regencia-comparativa-cifras small{display:block;font-size:.73rem;color:var(--ui-muted);margin-top:.4rem;font-weight:400}.regencia-comparativa-barras{display:grid;gap:.35rem}.regencia-comparativa-barras .regencia-pista{display:block}.regencia-comparativa-barras i{background:var(--barra-color);transform:scaleX(var(--proporcion));animation:regencia-barra-entrada .6s ease-out}.regencia-comparativa-cifras{font-size:.8rem}.regencia-tarjeta{transition:transform .2s,box-shadow .2s,border-color .2s}.regencia-tarjeta:hover{transform:translateY(-2px);border-color:var(--ui-primary);box-shadow:var(--ui-shadow-md)}.regencia-tarjeta-cifras{display:flex;gap:.6rem;flex-wrap:wrap}.regencia-tarjeta-cifras>span{display:flex;gap:.35rem;align-items:center;padding:.55rem .65rem;background:var(--ui-surface);border:1px solid var(--ui-border);border-radius:.6rem;font-size:.75rem;color:var(--ui-muted)}.regencia-tarjeta-cifras strong,.regencia-tarjeta-cifras i{color:var(--ui-primary)}.regencia-cronologia{grid-template-columns:1fr;border-left:2px solid var(--ui-border);margin-left:.6rem;padding-left:1.5rem}.regencia-cronologia .regencia-tarjeta{position:relative}.regencia-cronologia .regencia-tarjeta:before{content:'';position:absolute;width:.8rem;height:.8rem;left:-2rem;top:1.6rem;border-radius:50%;background:var(--ui-primary);box-shadow:0 0 0 4px var(--ui-primary-soft)}.regencia-comparativa-fila:focus-visible{outline:2px solid var(--ui-primary);outline-offset:3px}@keyframes regencia-barra-entrada{from{transform:scaleX(0)}to{transform:scaleX(var(--proporcion))}}@media(max-width:850px){.regencia-comparativa-fila{grid-template-columns:1fr 1fr}.regencia-comparativa-nombre{grid-column:1/-1}}@media(max-width:600px){.regencia-resumen-estudiantes{grid-template-columns:1fr}.regencia-resumen-estudiantes>div{flex-direction:row;align-items:center;gap:1rem}.regencia-comparativa-fila{grid-template-columns:1fr}.regencia-cronologia{grid-template-columns:1fr}.regencia-cronologia .regencia-tarjeta:before{left:-2rem}}@media(prefers-reduced-motion:reduce){.regencia-comparativa-barras i{animation:none}.regencia-comparativa-fila,.regencia-tarjeta{transition:none}.regencia-comparativa-fila:hover,.regencia-tarjeta:hover{transform:none}}
</style>
@endpush
@endonce
